onRoleReachedMoon = function()    game.pauseLogic()	if global.isLevelPassed(28) and global.isLevelPassed(29) then		if global.getBool("stg_b2") then dialog.setSkipEnabled(true) end		repeat			sound.play("49-1")			if dialog.show("Stage2F-1", faceWunai) ==1 then break end			if dialog.show("Stage2F-2", faceBujie) ==1 then break end			if dialog.show("Stage2F-3", faceZhoumei) ==1 then break end			if dialog.show("Stage2F-4", facePutong) ==1 then break end			if dialog.show("Stage2F-5", faceDeyi) ==1 then break end			sound.play("60-1")			if dialog.show("Stage2F-6", faceManyi) ==1 then break end			global.setBool("stg_b2")		until true		dialog.setSkipEnabled(false)    end    game.success()end